            if len(deleted) == 0:
                sys.stderr.write("error: denied\n")
                sys.exit(3)

            result = {
                "ref": args.ref,
                "deleted": True
            }
            print(json.dumps(result))
            return 0

    finally:
        client.close()

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
